mapper.delete:
DELETE
FROM t_workspace_mapping
WHERE workspace_id #{workspaceId}
AND source = #{source}

mapper.update:
UPDATE t_workspace_mapping
SET workspace_id      = #{workspaceId},
    mapping_id        = #{mappingId},
    extension_content = #{extensionContent},
    source            = #{source}
WHERE id = #{id}

mapper.select:
SELECT id, workspace_id, mapping_id, extension_content, source
FROM t_workspace_mapping
WHERE workspace_id = #{workspaceId}
